import heapq
import itertools


class Helpdesk:
    PRIORITIES = ("normal", "high", "critical")

    def __init__(self) -> None:
        self._customers: dict[str, bool] = {}  # name -> vip
        self._tickets: dict[int, dict] = {}    # id -> ticket data
        self._queue: list = []                 # heap
        self._counter = itertools.count()
        self._next_id = 1
        self._closed: set[int] = set()

    def add_customer(self, name: str, vip: bool = False) -> None:
        self._customers[name] = vip

    def _priority_key(self, priority: str) -> int:
        # higher priority -> smaller key
        return -self.PRIORITIES.index(priority)

    def _push_to_queue(self, ticket_id: int) -> None:
        t = self._tickets[ticket_id]
        vip = self._customers.get(t["customer"], False)
        # VIP before everyone; then by priority; then FIFO
        key = (0 if vip else 1, self._priority_key(t["priority"]), next(self._counter))
        heapq.heappush(self._queue, (key, ticket_id))

    def open_ticket(self, customer: str, title: str, priority: str = "normal") -> int:
        if not title:
            raise ValueError("Ticket title cannot be empty.")
        if priority not in self.PRIORITIES:
            raise ValueError(f"Invalid priority: {priority}")
        if customer not in self._customers:
            self._customers[customer] = False
        ticket_id = self._next_id
        self._next_id += 1
        self._tickets[ticket_id] = {
            "customer": customer,
            "title": title,
            "priority": priority,
            "status": "open",
        }
        self._push_to_queue(ticket_id)
        return ticket_id

    def next_ticket(self) -> int | None:
        while self._queue:
            _, ticket_id = heapq.heappop(self._queue)
            status = self._tickets[ticket_id]["status"]
            if status == "open":
                self._tickets[ticket_id]["status"] = "in_progress"
                return ticket_id
            # if it was closed while queued (shouldn't happen) or already taken, skip
        return None

    def close(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        self._tickets[ticket_id]["status"] = "closed"

    def reopen(self, ticket_id: int) -> None:
        if ticket_id not in self._tickets:
            raise ValueError(f"Unknown ticket id: {ticket_id}")
        if self._tickets[ticket_id]["status"] == "closed":
            raise ValueError("Cannot reopen a closed ticket.")
        self._tickets[ticket_id]["status"] = "open"
        self._push_to_queue(ticket_id)
